import bisect

def ks_stat(a, b):
    sa, sb = sorted(a), sorted(b)
    d = 0.0
    for x in sorted(set(sa) | set(sb)):
        fa = bisect.bisect_right(sa, x) / len(sa)
        fb = bisect.bisect_right(sb, x) / len(sb)
        d = max(d, abs(fa - fb))
    return round(d, 4)
